CREATE TABLE public.profiles (id uuid PRIMARY KEY REFERENCES auth.users(id) ON DELETE CASCADE, name text NOT NULL DEFAULT '' CHECK (char_length(name)<=40), photo_path text, birthday date, anniversary date);
GRANT SELECT, UPDATE ON public.profiles TO authenticated;
GRANT ALL ON public.profiles TO service_role;
ALTER TABLE public.profiles ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.relationships (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), anniversary date NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.relationships TO authenticated;
GRANT ALL ON public.relationships TO service_role;
ALTER TABLE public.relationships ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.relationship_members (user_id uuid PRIMARY KEY REFERENCES public.profiles(id) ON DELETE CASCADE, relationship_id uuid NOT NULL REFERENCES public.relationships(id) ON DELETE CASCADE);
GRANT SELECT ON public.relationship_members TO authenticated;
GRANT ALL ON public.relationship_members TO service_role;
ALTER TABLE public.relationship_members ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.partner_invitations (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), owner_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE, code text UNIQUE NOT NULL DEFAULT upper(replace(gen_random_uuid()::text,'-','')), joiner_id uuid REFERENCES public.profiles(id) ON DELETE CASCADE, status text NOT NULL DEFAULT 'open' CHECK(status IN ('open','pending','accepted','cancelled')), expires_at timestamptz NOT NULL DEFAULT now()+interval '7 days', created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.partner_invitations TO authenticated;
GRANT ALL ON public.partner_invitations TO service_role;
ALTER TABLE public.partner_invitations ENABLE ROW LEVEL SECURITY;
CREATE FUNCTION public.my_relationship() RETURNS uuid LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$ SELECT relationship_id FROM public.relationship_members WHERE user_id=auth.uid() $$;
REVOKE ALL ON FUNCTION public.my_relationship() FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.my_relationship() TO authenticated;
CREATE FUNCTION public.is_my_partner(target uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$ SELECT EXISTS(SELECT 1 FROM public.relationship_members a JOIN public.relationship_members b ON a.relationship_id=b.relationship_id WHERE a.user_id=auth.uid() AND b.user_id=target) $$;
REVOKE ALL ON FUNCTION public.is_my_partner(uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.is_my_partner(uuid) TO authenticated;
CREATE POLICY profiles_read ON public.profiles FOR SELECT TO authenticated USING(id=auth.uid() OR public.is_my_partner(id));
CREATE POLICY profiles_update ON public.profiles FOR UPDATE TO authenticated USING(id=auth.uid()) WITH CHECK(id=auth.uid());
CREATE POLICY relationships_read ON public.relationships FOR SELECT TO authenticated USING(id=public.my_relationship());
CREATE POLICY members_read ON public.relationship_members FOR SELECT TO authenticated USING(relationship_id=public.my_relationship());
CREATE POLICY invitations_read ON public.partner_invitations FOR SELECT TO authenticated USING(owner_id=auth.uid() OR joiner_id=auth.uid());
CREATE FUNCTION public.create_user_profile() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ BEGIN INSERT INTO public.profiles(id) VALUES(NEW.id); RETURN NEW; END $$;
REVOKE ALL ON FUNCTION public.create_user_profile() FROM PUBLIC;
CREATE TRIGGER create_profile_on_signup AFTER INSERT ON auth.users FOR EACH ROW EXECUTE FUNCTION public.create_user_profile();
CREATE FUNCTION public.save_profile(p_name text,p_birthday date,p_anniversary date,p_photo_path text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Sign in first'; END IF; IF length(trim(p_name)) NOT BETWEEN 1 AND 40 OR p_anniversary IS NULL OR p_anniversary>current_date OR p_birthday>current_date THEN RAISE EXCEPTION 'Enter a valid name and dates that are not in the future'; END IF; IF p_photo_path IS NOT NULL AND split_part(p_photo_path,'/',1)<>auth.uid()::text THEN RAISE EXCEPTION 'Invalid photo'; END IF; INSERT INTO public.profiles(id,name,birthday,anniversary,photo_path) VALUES(auth.uid(),trim(p_name),p_birthday,p_anniversary,p_photo_path) ON CONFLICT(id) DO UPDATE SET name=excluded.name,birthday=excluded.birthday,anniversary=excluded.anniversary,photo_path=excluded.photo_path; END $$;
CREATE FUNCTION public.create_partner_invitation() RETURNS public.partner_invitations LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE result public.partner_invitations; BEGIN IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Sign in first'; END IF; PERFORM 1 FROM public.profiles WHERE id=auth.uid() AND name<>'' AND anniversary IS NOT NULL FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION 'Complete your profile first'; END IF; IF public.my_relationship() IS NOT NULL THEN RAISE EXCEPTION 'You already have a partner'; END IF; SELECT * INTO result FROM public.partner_invitations WHERE owner_id=auth.uid() AND status IN ('open','pending') AND expires_at>now() ORDER BY created_at DESC LIMIT 1; IF FOUND THEN RETURN result; END IF; INSERT INTO public.partner_invitations(owner_id) VALUES(auth.uid()) RETURNING * INTO result; RETURN result; END $$;
CREATE FUNCTION public.join_partner_invitation(p_code text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE inv public.partner_invitations; BEGIN IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Sign in first'; END IF; SELECT * INTO inv FROM public.partner_invitations WHERE code=upper(trim(p_code)) FOR UPDATE; IF NOT FOUND OR inv.status<>'open' OR inv.expires_at<=now() THEN RAISE EXCEPTION 'This code is invalid, expired, or already used'; END IF; IF inv.owner_id=auth.uid() THEN RAISE EXCEPTION 'Use your partner''s code, not your own'; END IF; IF NOT EXISTS(SELECT 1 FROM public.profiles WHERE id=auth.uid() AND name<>'' AND anniversary IS NOT NULL) THEN RAISE EXCEPTION 'Complete your profile first'; END IF; IF public.my_relationship() IS NOT NULL THEN RAISE EXCEPTION 'You already have a partner'; END IF; IF EXISTS(SELECT 1 FROM public.partner_invitations WHERE (joiner_id=auth.uid() OR owner_id=auth.uid()) AND status='pending' AND expires_at>now()) THEN RAISE EXCEPTION 'Resolve your existing request first'; END IF; UPDATE public.partner_invitations SET joiner_id=auth.uid(),status='pending' WHERE id=inv.id; END $$;
CREATE FUNCTION public.resolve_partner_invitation(p_id uuid,p_accept boolean) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE inv public.partner_invitations; rel uuid; anniversary_date date; BEGIN IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Sign in first'; END IF; SELECT * INTO inv FROM public.partner_invitations WHERE id=p_id FOR UPDATE; IF NOT FOUND OR (inv.owner_id<>auth.uid() AND inv.joiner_id IS DISTINCT FROM auth.uid()) THEN RAISE EXCEPTION 'Request not available'; END IF; IF NOT p_accept THEN IF inv.status NOT IN ('open','pending') THEN RAISE EXCEPTION 'Request already resolved'; END IF; UPDATE public.partner_invitations SET status='cancelled' WHERE id=inv.id; RETURN; END IF; IF inv.owner_id<>auth.uid() OR inv.status<>'pending' OR inv.joiner_id IS NULL OR inv.expires_at<=now() THEN RAISE EXCEPTION 'Request is not awaiting your approval or has expired'; END IF; PERFORM 1 FROM public.profiles WHERE id IN(inv.owner_id,inv.joiner_id) ORDER BY id FOR UPDATE; IF EXISTS(SELECT 1 FROM public.relationship_members WHERE user_id IN(inv.owner_id,inv.joiner_id)) THEN RAISE EXCEPTION 'One of you is already connected'; END IF; SELECT anniversary INTO anniversary_date FROM public.profiles WHERE id=inv.owner_id; IF anniversary_date IS NULL THEN RAISE EXCEPTION 'Save your anniversary first'; END IF; INSERT INTO public.relationships(anniversary) VALUES(anniversary_date) RETURNING id INTO rel; INSERT INTO public.relationship_members(user_id,relationship_id) VALUES(inv.owner_id,rel),(inv.joiner_id,rel); UPDATE public.partner_invitations SET status='accepted' WHERE id=inv.id; UPDATE public.partner_invitations SET status='cancelled' WHERE id<>inv.id AND status IN ('open','pending') AND (owner_id IN(inv.owner_id,inv.joiner_id) OR joiner_id IN(inv.owner_id,inv.joiner_id)); END $$;
REVOKE ALL ON FUNCTION public.save_profile(text,date,date,text), public.create_partner_invitation(), public.join_partner_invitation(text), public.resolve_partner_invitation(uuid,boolean) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.save_profile(text,date,date,text), public.create_partner_invitation(), public.join_partner_invitation(text), public.resolve_partner_invitation(uuid,boolean) TO authenticated;
CREATE POLICY photo_read ON storage.objects FOR SELECT TO authenticated USING(bucket_id='profile-photos' AND ((storage.foldername(name))[1]=auth.uid()::text OR EXISTS(SELECT 1 FROM public.profiles WHERE photo_path=name AND public.is_my_partner(id))));
CREATE POLICY photo_insert ON storage.objects FOR INSERT TO authenticated WITH CHECK(bucket_id='profile-photos' AND (storage.foldername(name))[1]=auth.uid()::text AND lower(storage.extension(name)) IN ('jpg','jpeg','png','webp'));
CREATE POLICY photo_delete ON storage.objects FOR DELETE TO authenticated USING(bucket_id='profile-photos' AND (storage.foldername(name))[1]=auth.uid()::text);